ALTER TABLE "sliper"."posts" ADD CONSTRAINT "posts_application_url" CHECK ("sliper"."posts"."application_url" is null or ("sliper"."posts"."kind" = '모집' and "sliper"."posts"."application_url" ~ '^https?://[^[:space:]]+$'));